<?php
namespace App\Services;
use Illuminate\Support\Facades\DB; use RuntimeException;
/** Target module intentionally guarded: grading tables are absent in supplied dump. */
class RaporService { public function assertSchemaAvailable():void { foreach(['nilai_siswa','komponen_penilaian','skala_predikat','rapor','detail_rapor','cetak_rapor'] as $t) if(!DB::getSchemaBuilder()->hasTable($t)) throw new RuntimeException("Tabel target {$t} belum ada; implementasi final memerlukan schema approval."); } public function nilaiAkhir(int $anggota,int $mapel,int $semester):array { $this->assertSchemaAvailable(); $rows=DB::table('nilai_siswa as n')->join('komponen_penilaian as c','c.id_komponen','=','n.id_komponen')->where('n.id_anggota',$anggota)->where('n.id_mapel',$mapel)->where('n.id_semester',$semester)->select('n.nilai','c.bobot_persen')->get(); if($rows->isEmpty()) throw new RuntimeException('Nilai komponen belum tersedia.'); if(abs((float)$rows->sum('bobot_persen')-100.0)>0.0001) throw new RuntimeException('Bobot komponen harus berjumlah 100%.'); $nilai=$rows->sum(fn($r)=>(float)$r->nilai*(float)$r->bobot_persen/100); $predikat=DB::table('skala_predikat')->where('nilai_min','<=',$nilai)->where('nilai_maks','>=',$nilai)->first(); if(!$predikat) throw new RuntimeException('Skala predikat tidak ditemukan.'); return ['nilai_akhir'=>round($nilai,2),'id_predikat'=>$predikat->id_predikat,'huruf'=>$predikat->huruf]; } }
